#!/usr/bin/env bash
set -euo pipefail
task_game_root="$(pwd -P)"
[[ -f "$task_game_root/package.json" && -f "$task_game_root/scripts/phone-update.js" ]] || { printf 'Entre na pasta do jogo antes: cd ~/ben10-v34/game\n' >&2; exit 1; }
command -v node >/dev/null || { printf 'Node não encontrado. Use a sessão Termux onde o jogo foi instalado.\n' >&2; exit 1; }
task_repair_stage="$(mktemp -d "${TMPDIR:-/tmp}/ben10-reparo.XXXXXXXX")"
trap 'rm -rf -- "$task_repair_stage"' EXIT
node --input-type=module - "$task_repair_stage" "$task_game_root" <<'BEN10_REPAIR_JS'
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
const files=[
  {
    "name": "scripts/termux-packages.sh",
    "sha256": "766e5efb8e1ba7145bca71913ee71ed262bb6a45da51befa1e0ea3230396072a",
    "content": "#!/usr/bin/env bash\n# Install missing official Termux tools without refreshing unrelated repositories.\nset -euo pipefail\ntask_missing=()\ntask_has_package() {\n  case \"$1\" in\n    git|cmake|ninja|curl|proot-distro) command -v \"$1\" >/dev/null 2>&1 ;;\n    clang) command -v clang >/dev/null 2>&1 && command -v clang++ >/dev/null 2>&1 ;;\n    python) command -v python3 >/dev/null 2>&1 || command -v python >/dev/null 2>&1 ;;\n    libandroid-spawn) [[ \"$(dpkg-query -W -f='${Status}' libandroid-spawn 2>/dev/null || true)\" == 'install ok installed' ]] ;;\n    *) printf 'Pacote não previsto neste instalador: %s\\n' \"$1\" >&2; return 2 ;;\n  esac\n}\nfor task_package in \"$@\"; do\n  case \"$task_package\" in git|cmake|ninja|clang|python|curl|libandroid-spawn|proot-distro) ;; *) printf 'Pacote inválido: %s\\n' \"$task_package\" >&2; exit 1 ;; esac\n  if ! task_has_package \"$task_package\"; then task_missing+=(\"$task_package\"); fi\ndone\nif ((${#task_missing[@]} == 0)); then\n  printf 'Ferramentas da IA já disponíveis. Sem consultar pkg/apt ou repositórios extras.\\n'\n  exit 0\nfi\n[[ -n \"${PREFIX:-}\" && -d \"$PREFIX/etc/apt\" ]] && command -v apt-get >/dev/null 2>&1 || {\n  printf 'APT do Termux não encontrado. Execute este instalador no Termux atualizado.\\n' >&2\n  exit 1\n}\numask 077\ntask_apt_work=\"$(mktemp -d \"${TMPDIR:-$PREFIX/tmp}/ben10-apt.XXXXXXXX\")\"\ntrap 'rm -rf -- \"$task_apt_work\"' EXIT\nmkdir -p \"$task_apt_work/lists/partial\" \"$task_apt_work/sources.list.d\"\n# Prefer the edition's actual Deb822 main file. APT itself parses Signed-By,\n# including inline public keys; do not convert it or substitute another edition.\ntask_main_file=\"$task_apt_work/termux.sources\"\nif [[ -f \"$PREFIX/etc/apt/sources.list.d/termux.sources\" ]]; then\n  task_unsafe_deb822='^[[:space:]]*(trusted|allow-insecure|allow-weak|allow-downgrade-to-insecure)[[:space:]]*:[[:space:]]*(yes|true|1)([[:space:]]|$)'\n  while IFS= read -r task_line || [[ -n \"$task_line\" ]]; do\n    if [[ \"${task_line,,}\" =~ $task_unsafe_deb822 ]]; then\n      printf 'A fonte principal contém uma opção que dispensa autenticação. A instalação parou sem enfraquecer assinaturas.\\n' >&2\n      exit 1\n    fi\n  done < \"$PREFIX/etc/apt/sources.list.d/termux.sources\"\n  cp -- \"$PREFIX/etc/apt/sources.list.d/termux.sources\" \"$task_main_file\"\n  printf 'Fonte principal: termux.sources existente (formato Deb822).\\n'\nelse\n  task_main_source=''\n  task_main_pattern='^[[:space:]]*deb[[:space:]]+(\\[[^]]*\\][[:space:]]+)?(https://termux\\.net/?|https://packages\\.termux\\.dev/apt/termux-main/?)[[:space:]]+stable[[:space:]]+main[[:space:]]*$'\n  task_unsafe_pattern='(trusted|allow-insecure|allow-weak|allow-downgrade-to-insecure)[[:space:]]*=[[:space:]]*(yes|true|1)'\n  for task_source_file in \"$PREFIX/etc/apt/sources.list\" \"$PREFIX\"/etc/apt/sources.list.d/*.list; do\n    [[ -f \"$task_source_file\" ]] || continue\n    while IFS= read -r task_line || [[ -n \"$task_line\" ]]; do\n      task_entry=\"${task_line%%#*}\"\n      if [[ \"$task_entry\" =~ $task_main_pattern && ! \"${task_entry,,}\" =~ $task_unsafe_pattern ]]; then\n        task_main_source=\"$task_entry\"\n        break 2\n      fi\n    done < \"$task_source_file\"\n  done\n  if [[ -z \"$task_main_source\" ]]; then\n    printf 'Não localizei a fonte principal configurada. Nenhum endereço alternativo foi selecionado. Confira sources.list.d/termux.sources.\\n' >&2\n    exit 1\n  fi\n  task_main_file=\"$task_apt_work/termux.list\"\n  printf '%s\\n' \"$task_main_source\" > \"$task_main_file\"\nfi\ntask_apt_options=(\n  -o \"Dir::Etc::sourcelist=$task_main_file\"\n  -o \"Dir::Etc::sourceparts=$task_apt_work/sources.list.d\"\n  -o \"Dir::State::lists=$task_apt_work/lists\"\n  -o \"Dir::Cache::pkgcache=$task_apt_work/pkgcache.bin\"\n  -o \"Dir::Cache::srcpkgcache=$task_apt_work/srcpkgcache.bin\"\n  -o \"APT::Update::Error-Mode=any\"\n  -o \"Acquire::AllowInsecureRepositories=false\"\n  -o \"Acquire::AllowDowngradeToInsecureRepositories=false\"\n  -o \"APT::Get::AllowUnauthenticated=false\"\n)\nprintf 'Instalando somente ferramentas ausentes: %s\\n' \"${task_missing[*]}\"\nprintf 'Usando somente o repositório principal oficial com assinaturas verificadas; fontes extras permanecem intactas.\\n'\nif ! apt-get \"${task_apt_options[@]}\" update; then\n  printf 'A atualização verificada da fonte principal falhou. A instalação da IA parou; nenhuma assinatura foi ignorada.\\n' >&2\n  exit 1\nfi\nif ! apt-get \"${task_apt_options[@]}\" install -y --no-install-recommends \"${task_missing[@]}\"; then\n  printf 'Não foi possível instalar as ferramentas pelo repositório oficial. A instalação da IA não foi concluída.\\n' >&2\n  exit 1\nfi\nfor task_package in \"${task_missing[@]}\"; do\n  task_has_package \"$task_package\" || { printf 'Ferramenta ainda ausente: %s\\n' \"$task_package\" >&2; exit 1; }\ndone\nprintf 'Ferramentas prontas. Repositórios extras não foram alterados.\\n'\n"
  },
  {
    "name": "scripts/local-ai/install.sh",
    "sha256": "32a341cd4a33e08f997e07a5d141786fd65430b63adaff51c681295a4b999478",
    "content": "#!/usr/bin/env bash\nset -euo pipefail\ntask_game_root=\"$(cd -- \"$(dirname -- \"$0\")/../..\" && pwd)\"\ntask_local_root=\"${BEN10_LOCAL_ROOT:-$HOME/.local/share/ben10-local-ai}\"\ntask_model=gt3\nwhile (($#)); do\n  case \"$1\" in\n    --model) (($# >= 2)) || { printf 'Informe gt3 ou light após --model.\\n' >&2; exit 1; }; task_model=\"$2\"; shift 2 ;;\n    --help|-h) printf 'bash local-ai.sh install [--model gt3|light]\\n'; exit 0 ;;\n    *) printf 'Argumento inválido: %s\\n' \"$1\" >&2; exit 1 ;;\n  esac\ndone\n[[ \"$task_model\" == gt3 || \"$task_model\" == light ]] || { printf 'Modelo: gt3 ou light\\n' >&2; exit 1; }\ncommand -v pkg >/dev/null && [[ \"$(uname -m)\" == aarch64 ]] || { printf 'Este instalador é para Termux Android ARM64. O painel pode usar serviços locais já instalados em outros sistemas.\\n' >&2; exit 1; }\ncommand -v node >/dev/null || { printf 'Execute bash install.sh do jogo primeiro.\\n' >&2; exit 1; }\numask 077\nmkdir -p \"$task_local_root/logs\"\nprintf 'IA local: instalação inicial usa internet e vários GB. Perfil: %s.\\n' \"$task_model\"\nbash \"$task_game_root/scripts/termux-packages.sh\" git cmake ninja clang python curl libandroid-spawn proot-distro\npython3 \"$task_game_root/scripts/local-ai/download_models.py\" --root \"$task_local_root\" --model \"$task_model\"\ntask_llama_revision=6c01da6278ab6c69ed67d9124806b50d2b299ba7\nif [[ ! -d \"$task_local_root/llama.cpp/.git\" ]]; then\n  git init \"$task_local_root/llama.cpp\"\n  git -C \"$task_local_root/llama.cpp\" remote add origin https://github.com/ggml-org/llama.cpp.git\nfi\nif ! git -C \"$task_local_root/llama.cpp\" cat-file -e \"$task_llama_revision^{commit}\" 2>/dev/null; then\n  git -C \"$task_local_root/llama.cpp\" fetch --depth 1 origin \"$task_llama_revision\"\nfi\ngit -C \"$task_local_root/llama.cpp\" checkout --detach \"$task_llama_revision\"\ncmake -S \"$task_local_root/llama.cpp\" -B \"$task_local_root/llama.cpp/build\" -G Ninja -DCMAKE_BUILD_TYPE=Release -DGGML_OPENMP=OFF -DGGML_LLAMAFILE=OFF -DLLAMA_OPENSSL=OFF -DLLAMA_BUILD_TESTS=OFF\ncmake --build \"$task_local_root/llama.cpp/build\" --target llama-server --parallel 4\nif ! proot-distro login ben10-ai -- /bin/true >/dev/null 2>&1; then\n  task_proot_help=\"$(proot-distro install --help 2>&1)\"\n  if [[ \"$task_proot_help\" == *'--name'* ]]; then\n    proot-distro install debian:bookworm --name ben10-ai\n  else\n    proot-distro install --override-alias ben10-ai debian\n  fi\nfi\nproot-distro login --bind \"$task_game_root/scripts/local-ai:/opt/ben10-worker\" ben10-ai -- /bin/bash -lc 'set -e; export DEBIAN_FRONTEND=noninteractive; apt-get update; apt-get install -y python3 python3-venv ca-certificates libgomp1; python3 -m venv /opt/ben10-voice; /opt/ben10-voice/bin/pip install --disable-pip-version-check -r /opt/ben10-worker/requirements.txt; /opt/ben10-voice/bin/python -c \"from piper import PiperVoice; import onnxruntime; print(\\\"Bibliotecas de voz prontas\\\")\"'\nprintf '\\nInstalação concluída. Inicie com: bash local-ai.sh start\\n'\n"
  },
  {
    "name": "local-ai.sh",
    "sha256": "5bc138bdcaed1aa2a3e6e9ae247ce72f43e4067dc95df98da11897ae4ad635cb",
    "content": "#!/usr/bin/env bash\nset -euo pipefail\ntask_game_root=\"$(cd -- \"$(dirname -- \"$0\")\" && pwd)\"\ntask_local_root=\"${BEN10_LOCAL_ROOT:-$HOME/.local/share/ben10-local-ai}\"\ntask_command=\"${1:-help}\"\nshift || true\ncase \"$task_command\" in\n  install) exec bash \"$task_game_root/scripts/local-ai/install.sh\" \"$@\" ;;\n  start|status)\n    task_node_options=()\n    if [[ -f \"$task_game_root/.env\" ]]; then task_node_options+=(\"--env-file=$task_game_root/.env\"); fi\n    exec node \"${task_node_options[@]}\" \"$task_game_root/scripts/local-ai/run.js\" \"$task_command\"\n    ;;\n  help|--help|-h)\n    printf 'Instalar uma vez: bash local-ai.sh install [--model gt3|light]\\nIniciar IA e jogo: bash local-ai.sh start\\nDiagnóstico: bash local-ai.sh status\\nModelos: %s\\n' \"$task_local_root\"\n    ;;\n  *) printf 'Comando inválido. Use bash local-ai.sh help\\n' >&2; exit 1 ;;\nesac\n"
  },
  {
    "name": "scripts/local-ai/run.js",
    "sha256": "537e85e222a844771a203ce31943859c492d71edc55750330c16d1cb893568e4",
    "content": "import {spawn} from 'node:child_process';\nimport {createConnection} from 'node:net';\nimport {readFile,mkdir,access,open} from 'node:fs/promises';\nimport {constants,existsSync} from 'node:fs';\nimport {fileURLToPath} from 'node:url';\nimport path from 'node:path';\nimport os from 'node:os';\nimport {localHealth,loopbackRequest,localSettings} from '../../server/local-ai.js';\nimport {BUILD_ID} from '../../public/release.js';\n\nconst gameRoot=fileURLToPath(new URL('../../',import.meta.url));\nconst localRoot=path.resolve(process.env.BEN10_LOCAL_ROOT||path.join(os.homedir(),'.local/share/ben10-local-ai'));\nconst pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));\nconst children=[];let stopping=false;\nasync function cleanup(){if(stopping)return;stopping=true;for(const child of [...children].reverse())if(child.exitCode===null&&child.signalCode===null){try{process.kill(-child.pid,'SIGTERM');}catch{child.kill('SIGTERM');}}await pause(500);}\nfor(const signal of ['SIGINT','SIGTERM'])process.once(signal,()=>cleanup().then(()=>process.exit(0)));\nfunction launch(command,args,{log,cwd=gameRoot}={}){\n if(stopping)throw Error('Inicialização cancelada');\n const child=spawn(command,args,{cwd,env:process.env,detached:true,stdio:log?['ignore',log,log]:'inherit'});\n children.push(child);child.on('error',error=>{child.startError=error;});return child;\n}\nfunction portOpen(port){return new Promise(resolve=>{const socket=createConnection({host:'127.0.0.1',port});const done=value=>{socket.destroy();resolve(value);};socket.setTimeout(700,()=>done(false));socket.once('connect',()=>done(true));socket.once('error',()=>done(false));});}\nasync function waitReady(read,predicate,child,label,timeout=180000){const deadline=Date.now()+timeout;let last=0;while(Date.now()<deadline&&!stopping){if(child&&(child.exitCode!==null||child.signalCode!==null||child.startError))throw Error(label+' encerrou. Consulte os logs em '+path.join(localRoot,'logs'));try{const value=await read();if(predicate(value))return value;}catch{}if(Date.now()-last>10000){console.log('Carregando '+label+'…');last=Date.now();}await pause(500);}throw Error(label+' não ficou pronto. Confira bash local-ai.sh status e os logs.');}\nasync function main(){\n const command=process.argv[2]||'status',settings=localSettings();let manifest=null;try{manifest=JSON.parse(await readFile(path.join(localRoot,'install.json'),'utf8'));}catch{}\n if(command==='status'){console.log(JSON.stringify({installed:!!manifest,model:manifest?.textRepo||null,modelsDirectory:localRoot,...await localHealth(settings)},null,2));return;}\n if(command!=='start')throw Error('Use start ou status');\n if(!manifest)throw Error('Instale primeiro: bash local-ai.sh install');\n const llama=path.join(localRoot,'llama.cpp/build/bin/llama-server');\n await access(llama,constants.X_OK).catch(()=>{throw Error('llama-server ausente. Complete bash local-ai.sh install.');});\n for(const file of [manifest.textModel,manifest.voiceModel,manifest.voiceModel+'.json'])await access(file);\n if(await portOpen(settings.textPort)||await portOpen(settings.voicePort))throw Error('Uma porta da IA local já está ocupada. Se a IA já estiver pronta, execute bash start.sh. Confira bash local-ai.sh status.');\n await mkdir(path.join(localRoot,'logs'),{recursive:true});\n const llmLog=await open(path.join(localRoot,'logs/conversa.log'),'a'),voiceLog=await open(path.join(localRoot,'logs/voz.log'),'a');\n const llm=launch(llama,['--model',manifest.textModel,'--alias',settings.model,'--host','127.0.0.1','--port',String(settings.textPort),'--ctx-size','2048','--threads','4','--threads-batch','4','--batch-size','128','--ubatch-size','128','--parallel','1','--threads-http','2','--no-webui','--reasoning','off'],{log:llmLog.fd});\n const tts=launch('proot-distro',['login','--bind',localRoot+':/ben10-data','--bind',path.join(gameRoot,'scripts/local-ai')+':/opt/ben10-worker','ben10-ai','--','/opt/ben10-voice/bin/python','/opt/ben10-worker/tts_server.py','--model','/ben10-data/voices/pt_BR-faber-medium.onnx','--port',String(settings.voicePort)],{log:voiceLog.fd});\n await llmLog.close();await voiceLog.close();\n await Promise.all([waitReady(async()=>JSON.parse((await loopbackRequest(settings.textPort,'/health',{timeout:2500})).data),s=>s.status==='ok',llm,'conversa'),waitReady(async()=>JSON.parse((await loopbackRequest(settings.voicePort,'/health',{timeout:2500})).data),s=>s.ready===true,tts,'voz')]);\n const gamePort=Number(process.env.PORT||3000);if(!Number.isInteger(gamePort)||gamePort<1024||gamePort>65535)throw Error('PORT do jogo inválida');\n let game=null,health;try{health=JSON.parse((await loopbackRequest(gamePort,'/api/health',{timeout:1500})).data);}catch{}\n if(health){if(health.runtime?.root!==gameRoot.replace(/\\/$/,''))throw Error('A porta do jogo pertence a outra instalação. Pare essa sessão ou escolha outra PORT.');}\n else{if(await portOpen(gamePort))throw Error('A porta do jogo está ocupada.');game=launch(process.execPath,[...(existsSync(path.join(gameRoot,'.env'))?['--env-file=.env']:[]),'server/index.js']);await waitReady(async()=>JSON.parse((await loopbackRequest(gamePort,'/api/health',{timeout:1500})).data),s=>s.ok===true,game,'jogo',30000);}\n const saved=await loopbackRequest(gamePort,'/api/config',{body:{conversationProvider:'local',voiceProvider:'local',localAi:settings}});if(saved.status!==200)throw Error('Não foi possível selecionar IA local no jogo.');\n console.log('\\nConversa e voz locais prontas, sem chave. Abra http://127.0.0.1:'+gamePort+'/?v='+BUILD_ID+' e toque em ♫.');\n console.log('Mantenha esta sessão aberta. Ctrl+C encerra somente os processos iniciados por este comando.');\n while(!stopping){for(const [child,label] of [[llm,'conversa'],[tts,'voz'],...(game?[[game,'jogo']]:[])])if(child.exitCode!==null||child.signalCode!==null||child.startError)throw Error('O serviço de '+label+' encerrou. Confira '+path.join(localRoot,'logs'));await pause(1000);}\n}\nmain().catch(async error=>{console.error(error.message);await cleanup();process.exitCode=1;});\n"
  }
];
try {
 const [stage,root]=process.argv.slice(2);
 const pkg=JSON.parse(await readFile(path.join(root,'package.json'),'utf8'));
 if(pkg.name!=='linel-live-city'||!/^42\.(0|1|2)\./.test(pkg.version))throw Error('Este reparo é para a V42, V42.1 ou V42.2 do Ben. Entre na pasta correta do jogo.');
 await writeFile(path.join(stage,'package.json'),'{"type":"module"}');
 for(const file of files){
  const bytes=Buffer.from(file.content,'utf8');
  if(createHash('sha256').update(bytes).digest('hex')!==file.sha256)throw Error('Integridade do reparo inválida: '+file.name);
  const target=path.join(stage,file.name);await mkdir(path.dirname(target),{recursive:true});await writeFile(target,bytes);
  if(file.name.endsWith('.sh'))execFileSync('bash',['-n',target],{stdio:'inherit'});
  else execFileSync(process.execPath,['--check',target],{stdio:'inherit'});
 }
 const {installStaged}=await import(pathToFileURL(path.join(root,'scripts/phone-update.js')));
 const backup=path.join(root,'data/installer-backups',path.basename(stage));
 await installStaged(stage,root,{version:pkg.version,files:files.map(f=>f.name)},backup);
 console.log('Reparo do instalador aplicado. Scripts antigos guardados em '+backup);
 console.log('Fontes APT, chaves, .env, progresso e modelos locais foram preservados.');
 console.log('Agora execute: bash local-ai.sh install && bash local-ai.sh start');
} catch(error) {console.error('Reparo não concluído: '+error.message);process.exitCode=1;}
BEN10_REPAIR_JS
